import{_ as e,c as i,o as p,al as t}from"./chunks/framework.QMC68jD7.js";const b=JSON.parse('{"title":"1.发布小程序","description":"","frontmatter":{},"headers":[],"relativePath":"tech/小程序/05.小程序的发布和配置.md","filePath":"tech/小程序/05.小程序的发布和配置.md","lastUpdated":1777271852000}'),m={name:"tech/小程序/05.小程序的发布和配置.md"};function n(l,a,o,r,d,s){return p(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="_1-发布小程序" tabindex="-1">1.发布小程序 <a class="header-anchor" href="#_1-发布小程序" aria-label="Permalink to &quot;1.发布小程序&quot;">​</a></h1><ul><li>在微信开发者工具中，单击右上角【上传】，提交开发版本</li></ul><p><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692159766407-207c8db0-3f3d-4175-b556-5b370c05c7a3.png#averageHue=%23484747&amp;clientId=ue4ae98fb-b359-4&amp;from=paste&amp;id=ue7e926b0&amp;originHeight=101&amp;originWidth=1918&amp;originalType=binary&amp;ratio=1&amp;rotation=0&amp;showTitle=false&amp;size=28231&amp;status=done&amp;style=none&amp;taskId=u3b99283f-0d6a-4846-8648-fb011d1446a&amp;title=" alt="image.png"></p><ul><li>进入小程序管理后台 , 左侧菜单【管理】【版本管理】</li></ul><p><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692159887503-6aca0f21-3c05-463c-a29d-12990e25c517.png#averageHue=%2373cc63&amp;clientId=ue4ae98fb-b359-4&amp;from=paste&amp;height=921&amp;id=u898fe1bd&amp;originHeight=921&amp;originWidth=1884&amp;originalType=binary&amp;ratio=1&amp;rotation=0&amp;showTitle=false&amp;size=99941&amp;status=done&amp;style=none&amp;taskId=u32d699a8-5be0-4b5d-bbbc-37376c277ab&amp;title=&amp;width=1884" alt="image.png"></p><ul><li><p>开发版本中【体验版】二维码，可供体验者扫码，之后会有消息发至管理员微信，管理员【通过】后，即可体验</p></li><li><p>单击开发版本右侧【提交审核】，根据提示填写【审核资料】，选填的都可以不填，其它都保持默认即可</p></li></ul><p><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692165211682-b7c085b2-8fb5-462b-9fa9-85f1007a4b2f.png#averageHue=%23fdfdfd&amp;clientId=ue4ae98fb-b359-4&amp;from=paste&amp;height=919&amp;id=ue58d75b9&amp;originHeight=919&amp;originWidth=1237&amp;originalType=binary&amp;ratio=1&amp;rotation=0&amp;showTitle=false&amp;size=64822&amp;status=done&amp;style=none&amp;taskId=uaccade39-2e9e-4efe-aadb-7cfdf6bf39a&amp;title=&amp;width=1237" alt="image.png"></p><ul><li>提交后，可看到审核版本，等待官方审核（2023年8月16日，审核时间非常快，可能不到10分钟就能审核通过）</li><li>审核通过后，即可发布</li><li>发布后即显示在线上版本</li></ul><p><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692165268074-c128807b-3139-4601-8e17-d5dec4fe3339.png#averageHue=%23dce79d&amp;clientId=ue4ae98fb-b359-4&amp;from=paste&amp;height=839&amp;id=ub4af110c&amp;originHeight=839&amp;originWidth=1343&amp;originalType=binary&amp;ratio=1&amp;rotation=0&amp;showTitle=false&amp;size=59698&amp;status=done&amp;style=none&amp;taskId=u2f452a08-78ab-4f47-80ff-0ac397ac3bb&amp;title=&amp;width=1343" alt="image.png"></p><h1 id="_2-生成小程序二维码" tabindex="-1">2.生成小程序二维码 <a class="header-anchor" href="#_2-生成小程序二维码" aria-label="Permalink to &quot;2.生成小程序二维码&quot;">​</a></h1><ul><li>小程序管理后台，左侧最下方菜单 【设置】 【基本设置】</li></ul><p><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692165331096-7c584457-1fe8-4efc-b87b-dcf078f9e2cc.png#averageHue=%2346bf45&amp;clientId=ue4ae98fb-b359-4&amp;from=paste&amp;height=919&amp;id=u0b1b47ed&amp;originHeight=919&amp;originWidth=1825&amp;originalType=binary&amp;ratio=1&amp;rotation=0&amp;showTitle=false&amp;size=112311&amp;status=done&amp;style=none&amp;taskId=u7b887c90-e629-4e8b-90eb-7d8a1553338&amp;title=&amp;width=1825" alt="image.png"></p><ul><li>基本信息中 【小程序码及线下物料下载】，单击最右侧【下载】，即可下载普通二维码和小程序码</li></ul><p><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692165368938-3d2c9ea5-c282-4e0f-bdb7-0d5881ab8425.png#averageHue=%23fbfbfb&amp;clientId=ue4ae98fb-b359-4&amp;from=paste&amp;height=611&amp;id=u34ecd6fd&amp;originHeight=611&amp;originWidth=989&amp;originalType=binary&amp;ratio=1&amp;rotation=0&amp;showTitle=false&amp;size=35519&amp;status=done&amp;style=none&amp;taskId=u4d7a3b98-5441-49bf-b7be-31c75165af8&amp;title=&amp;width=989" alt="image.png"></p><h1 id="_3-打开小程序" tabindex="-1">3.打开小程序 <a class="header-anchor" href="#_3-打开小程序" aria-label="Permalink to &quot;3.打开小程序&quot;">​</a></h1><ul><li>可在小程序中搜索小程序名称（基本信息中有小程序名称）</li><li>也可直接扫描二维码</li></ul><h1 id="_4-发布后小程序不能请求接口数据" tabindex="-1">4.发布后小程序不能请求接口数据 <a class="header-anchor" href="#_4-发布后小程序不能请求接口数据" aria-label="Permalink to &quot;4.发布后小程序不能请求接口数据&quot;">​</a></h1><p>需要在小程序管理后台配置服务器域名，方可访问<br><img src="https://cdn.nlark.com/yuque/0/2023/png/8438658/1692165471957-4cf23f56-a805-4acf-b8e6-7d384b971265.png#averageHue=%23fdfdfd&amp;clientId=ue4ae98fb-b359-4&amp;from=paste&amp;height=618&amp;id=uc60595be&amp;originHeight=618&amp;originWidth=1351&amp;originalType=binary&amp;ratio=1&amp;rotation=0&amp;showTitle=false&amp;size=44515&amp;status=done&amp;style=none&amp;taskId=ud7e564cf-5101-4f7d-822d-7556480a793&amp;title=&amp;width=1351" alt="image.png"></p>',18)])])}const g=e(m,[["render",n]]);export{b as __pageData,g as default};
